package fraymus.workspace;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.awt.Color;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.json.*;

/** Unit boundary fixtures exercise admission/recovery. Actual Chromium actions have separate end-to-end tests. */
public class Agency043Test {
    static final class Fixture implements AutoCloseable {
        final Path root=Files.createTempDirectory("agency043-unit-");final WorkspaceStore store=new WorkspaceStore(root);final LearningStore learning=new LearningStore(root);final List<String> witnessed=new ArrayList<>();final String session=UUID.randomUUID().toString();Agency043 agency;long sequence;
        boolean failSurfaceWitness;
        Fixture(Agency043.Planner planner)throws Exception{agency=new Agency043(root,store,learning,planner,id->{},(k,d)->{if(failSurfaceWitness&&k.equals("task043-surface-action"))throw new java.io.IOException("Injected witness write failure");witnessed.add(k);},()->false,false);register();}
        void register()throws Exception{try(var in=Agency043Test.class.getResourceAsStream("/agency043/tool-schemas.json")){agency.register(new JSONObject().put("sourceSha256","a".repeat(64)).put("tools",new JSONArray(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8))));}}
        JSONObject start(String goal,String mode)throws Exception{return agency.start(new JSONObject().put("goal",goal).put("mode",mode).put("model","unit-boundary-fixture").put("visionModel",""));}
        JSONObject claim()throws Exception{return agency.claim(session);}
        JSONObject authority(JSONObject c){return new JSONObject().put("taskId",c.getString("taskId")).put("effectId",c.getString("id")).put("nonce",c.getString("nonce")).put("sessionId",session);}
        String frame(JSONObject c,String phase)throws Exception{String kind=c.getJSONObject("extra").optString("captureFocus",c.getString("tool").startsWith("browser.")?"browser":"canvas");var r=c.getJSONObject("extra").optJSONObject("artifact");var src=VisualMemory043Test.source(session,++sequence,kind,r==null?"":r.getString("id"),r==null?0:r.getInt("version"));var input=authority(c).put("phase",phase).put("source",src).put("png",Base64.getEncoder().encodeToString(ScreenPixels043Test.png(ScreenPixels043Test.image(phase.equals("after")?4:0,Color.BLUE))));return agency.frame(input).getString("id");}
        JSONObject acknowledge(JSONObject c,JSONObject result)throws Exception{String before=frame(c,"before"),after=frame(c,"after");return agency.acknowledge(authority(c).put("beforeId",before).put("afterId",after).put("duringIds",new JSONArray()).put("result",result));}
        JSONObject proof(JSONObject c,JSONArray steps)throws Exception{var a=c.getJSONObject("extra").getJSONObject("artifact");var checks=new JSONArray();for(int i=0;i<steps.length();i++)checks.put(new JSONObject().put("index",i).put("passed",true).put("expected",steps.get(i)));return store.recordTest(new JSONObject().put("id",a.getString("id")).put("version",a.getInt("version")).put("steps",steps).put("checks",checks));}
        public void close()throws Exception{agency.close();store.close();}
    }
    static JSONObject reply(String tool,JSONObject args){return new JSONObject().put("text",new JSONObject().put("tool",tool).put("args",args).toString()).put("localModel",new JSONObject().put("digest","b".repeat(64))).put("compute",new JSONObject().put("cpuOnly",true));}
    @Test public void registeredSchemasRejectInventedFieldsAndAssertionFreeTests()throws Exception{JSONArray defs;try(var in=getClass().getResourceAsStream("/agency043/tool-schemas.json")){defs=new JSONArray(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}for(Object raw:defs){var f=((JSONObject)raw).getJSONObject("function");if(f.getString("name").equals("canvas_test")){var s=f.getJSONObject("parameters");assertThrows(IllegalArgumentException.class,()->ToolSchema043.validate(s,new JSONObject("{\"steps\":[{\"selector\":\"#count\",\"action\":\"click\"}]}")));ToolSchema043.validate(s,new JSONObject().put("steps",Agency043.counterChecks()));assertThrows(IllegalArgumentException.class,()->ToolSchema043.validate(s,new JSONObject().put("steps",Agency043.counterChecks()).put("passed",true)));}}}
    @Test public void prematureModelFinishCannotCreateAnArtifactOrVisualRoutine()throws Exception{try(var f=new Fixture(request->reply("finish",new JSONObject().put("summary","claimed success")))){var g=f.start("Build an actual app","workbench");f.agency.tick();var c=f.claim();f.acknowledge(c,new JSONObject().put("observation",UUID.randomUUID().toString()).put("url","http://127.0.0.1/fixture").put("text","data").put("controls",new JSONArray()));for(int i=0;i<4;i++)f.agency.tick();var finalTask=f.agency.read(g.getString("id"));assertEquals("interrupted",finalTask.getString("status"));assertEquals(0,f.store.artifacts().length());assertEquals(0,f.agency.visual.state().getJSONArray("patterns").length());assertEquals("interrupted",f.learning.read("episode",finalTask.getString("episodeId")).getString("status"));}}
    @Test public void actualStoredReceiptAndFrozenCounterStepsAreRequiredBeforeClaimIsConsumed()throws Exception{
        var calls=new AtomicInteger();try(var f=new Fixture(request->calls.getAndIncrement()==0?reply("canvas.write",new JSONObject().put("title","Unit admission boundary").put("files",new JSONObject().put("index.html","<html><body>Unit boundary; actual browser execution is tested separately.</body></html>"))):reply("finish",new JSONObject().put("summary","Declared tests checked")))){
            var g=f.start("Build counter with Add and Reset","workbench");f.agency.tick();f.acknowledge(f.claim(),new JSONObject().put("observation",UUID.randomUUID().toString()).put("url","http://127.0.0.1/unit").put("controls",new JSONArray()));f.agency.tick();var open=f.claim();f.acknowledge(open,open.getJSONObject("extra").getJSONObject("artifact"));var test=f.claim();assertTrue(test.getJSONObject("args").getJSONArray("steps").similar(Agency043.counterChecks()));var a=f.agency.read(g.getString("id")).getJSONObject("artifact");
            var weak=new JSONArray().put(new JSONObject().put("selector","body").put("expectCount",1));var weakProof=f.store.recordTest(new JSONObject().put("id",a.getString("id")).put("version",a.getInt("version")).put("steps",weak).put("checks",new JSONArray().put(new JSONObject().put("passed",true))));assertThrows(IllegalStateException.class,()->f.acknowledge(test,weakProof));assertTrue(f.agency.read(g.getString("id")).has("claim"));assertFalse(f.agency.read(g.getString("id")).optString("status").equals("completed"));
            var checks=new JSONArray();for(int i=0;i<5;i++)checks.put(new JSONObject().put("passed",true));var valid=f.store.recordTest(new JSONObject().put("id",a.getString("id")).put("version",a.getInt("version")).put("steps",Agency043.counterChecks()).put("checks",checks));f.acknowledge(test,valid);f.agency.tick();assertEquals("completed",f.agency.read(g.getString("id")).getString("status"));assertEquals(1,calls.get());assertEquals(1,f.agency.read(g.getString("id")).getJSONObject("timing052").getInt("terminalChecksWithoutModel"));assertThrows(IllegalStateException.class,()->f.agency.requireExecution(g.getString("id"),test.getString("nonce")));
        }
    }
    @Test public void inspectionReportRequiresActualStoredMatchingReportAssertions()throws Exception{try(var f=new Fixture(request->{throw new AssertionError("Native inspection must not need a planner");})){var g=f.start("Inspect labelled software surface","inspect");f.agency.tick();f.acknowledge(f.claim(),new JSONObject());var c=f.claim();assertEquals("report",c.getString("kind"));var actual=f.proof(c,c.getJSONObject("extra").getJSONArray("steps"));f.acknowledge(c,actual);assertEquals("completed",f.agency.read(g.getString("id")).getString("status"));assertEquals(0,f.agency.visual.state().getJSONArray("patterns").length());assertTrue(f.witnessed.contains("task043-completed"));}}
    @Test public void claimedHostInterruptionRejectsOldNonceAndExplicitResumeStartsFreshObservation()throws Exception{try(var f=new Fixture(request->{throw new AssertionError();})){var g=f.start("Inspect for recovery","inspect");f.agency.tick();var old=f.claim();f.agency.detach(f.session);assertEquals("interrupted",f.agency.read(g.getString("id")).getString("status"));assertThrows(IllegalStateException.class,()->f.agency.frame(f.authority(old).put("phase","before").put("source",new JSONObject()).put("png","")));f.agency.control(g.getString("id"),"resume");f.agency.tick();var next=f.claim();assertNotEquals(old.getString("nonce"),next.getString("nonce"));assertEquals(2,next.getInt("generation"));}}
    @Test public void queuedAndClaimedTasksRestoreAsInterruptedWithoutSilentReplay()throws Exception{try(var f=new Fixture(request->{throw new AssertionError();})){var g=f.start("Inspect saved state","inspect");f.agency.tick();var old=f.claim();f.agency.close();f.agency=new Agency043(f.root,f.store,f.learning,request->{throw new AssertionError();},id->{},(kind,v)->{},()->false,false);assertEquals("interrupted",f.agency.read(g.getString("id")).getString("status"));assertThrows(IllegalStateException.class,()->f.agency.requireExecution(g.getString("id"),old.getString("nonce")));assertEquals(0,f.agency.state().getString("activeId").length());}}
    @Test public void commitFailureAfterConsumingHostClaimInterruptsInsteadOfWaitingForever()throws Exception{try(var f=new Fixture(request->{throw new AssertionError();})){var g=f.start("Inspect witness failure","inspect");f.agency.tick();var c=f.claim();f.failSurfaceWitness=true;assertThrows(java.io.IOException.class,()->f.acknowledge(c,new JSONObject()));var task=f.agency.read(g.getString("id"));assertEquals("interrupted",task.getString("status"));assertFalse(task.has("claim"));assertTrue(task.getString("reason").contains("could not commit"));}}
    @Test public void explicitScreenQuestionUsesNativeInspectionAndCounterCreationUsesOnlyTheCreationStage()throws Exception{try(var f=new Fixture(request->{assertEquals(List.of("canvas.write"),request.getJSONArray("allowedTools").toList());assertTrue(request.getString("prompt").contains("supply ONLY title and files"));return reply("finish",new JSONObject().put("summary","refused"));})){var look=f.start("Describe the workspace screen","workbench");assertEquals("inspect",look.getString("mode"));assertEquals("workspace",look.getString("focus"));f.agency.control(look.getString("id"),"cancel");var create=f.start("Create counter with Add and Reset","workbench");assertEquals("workbench",create.getString("mode"));f.agency.tick();f.acknowledge(f.claim(),new JSONObject());f.agency.tick();assertEquals(1,f.agency.read(create.getString("id")).getInt("failures"));}}
    @Test public void unverifiedConversationIsNotPresentedAsVerifiedOutcomeToTheContinuingBrain()throws Exception{try(var f=new Fixture(request->reply("finish",new JSONObject().put("summary","A descriptive response only")))){var g=f.start("Summarize the current information","workbench");f.agency.tick();f.acknowledge(f.claim(),new JSONObject());f.agency.tick();assertEquals("completed-unverified",f.agency.read(g.getString("id")).getString("outcome"));assertEquals("completed-unverified",f.agency.outcomes().getJSONObject(0).getString("status"));assertEquals(0,f.agency.visual.state().getJSONArray("patterns").length());}}
    @Test public void rejectedNativeModelSyntaxRetriesWithinBudgetWithoutExecutingRejectedArguments()throws Exception{var attempts=new AtomicInteger();try(var f=new Fixture(request->{if(attempts.getAndIncrement()==0)throw new java.io.IOException("Ollama: error parsing tool call: invalid trailing escape");return reply("canvas.write",new JSONObject().put("title","Explicit unit boundary").put("files",new JSONObject().put("index.html","<h1>Boundary fixture, not a browser execution claim</h1>")));})){var g=f.start("Create counter with Reset","workbench");f.agency.tick();f.acknowledge(f.claim(),new JSONObject());f.agency.tick();assertEquals(0,f.store.artifacts().length());var rejected=f.agency.read(g.getString("id"));assertEquals("ready",rejected.getString("status"));assertEquals(1,rejected.getInt("failures"));assertTrue(rejected.getJSONArray("history").toList().stream().anyMatch(raw->"plan-rejected".equals(((Map<?,?>)raw).get("kind"))));f.agency.tick();assertEquals(1,f.store.artifacts().length());assertEquals("waiting-host",f.agency.read(g.getString("id")).getString("status"));assertEquals(2,attempts.get());}}

    @Test public void missingActionAuthorityRefusesClearlyWhilePureDefinitionReadsRemainPassive()throws Exception{
        try(var f=new Fixture(request->{throw new AssertionError();})){
            var g=f.start("Inspect permission boundary","inspect");f.agency.tick();var claim=f.claim();
            var error=assertThrows(IllegalStateException.class,()->f.agency.requireExecution044(null,null,"/api/game/close",f.session));assertTrue(error.getMessage().contains("owns execution"));
            assertThrows(IllegalStateException.class,()->f.agency.requireExecution044(g.getString("id"),null,"/api/game/close",f.session));
            for(String route:List.of("/api/world/suite","/api/pose-study/suite","/api/push-learning/suite","/api/contact-study/suite"))assertTrue(route,WorkspaceServer.passive043(route));
            for(String route:List.of("/api/game/close","/api/world/start","/api/pose-study/start","/api/contact-study/start","/api/push-learning/start"))assertFalse(route,WorkspaceServer.passive043(route));
            f.agency.requireExecution044(g.getString("id"),claim.getString("nonce"),"/api/browser/observe",f.session);
        }
    }
}
